class Solution:
    def numPrimeArrangements(self, n: int) -> int:
        MOD = 10**9 + 7
        def is_prime(x):
            if x < 2:
                return False
            i = 2
            while i * i <= x:
                if x % i == 0:
                    return False
                i += 1
            return True
        p = sum(1 for x in range(2, n + 1) if is_prime(x))
        ans = 1
        for k in range(1, p + 1):
            ans = ans * k % MOD
        for k in range(1, n - p + 1):
            ans = ans * k % MOD
        return ans

