        if (x < 2) return false;
        for (int i = 2; (long long)i * i <= x; ++i)
            if (x % i == 0) return false;
        return true;
    }
    int numPrimeArrangements(int n) {
        const long long MOD = 1e9 + 7;
        int p = 0;
        for (int x = 2; x <= n; ++x)
            if (isPrime(x)) p++;
